package com.nth.desktop3d;

import android.app.Instrumentation;
import android.content.SharedPreferences;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import java.lang.reflect.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.BooleanSupplier;

/** Real drawer drag, page creation/cancel, sort preservation, rotation and preview regression. */
public final class Launcher070Smoke {
    private final Instrumentation test;private final MainActivity activity;private final String output;private LauncherStore store;private DesktopView desktop;
    public Launcher070Smoke(Instrumentation test,MainActivity activity,String output){this.test=test;this.activity=activity;this.output=output;}
    public void run()throws Exception{
        store=(LauncherStore)field("store");desktop=(DesktopView)field("desktop");Map<String,?> before=new HashMap<>(store.preferences.getAll());String layout=store.preferences.getString("layout","[]");int oldPage=store.page,oldTransition=store.transition,oldMode=store.mode;boolean oldReduced=store.reducedMotion;int oldCount=store.pageCount();
        try{
            await(()->Boolean.TRUE.equals(field("loaded")),"App catalog was not loaded before workspace tests");
            defaultFeed();
            main(()->{invoke("closePanel");store.mode=0;store.reducedMotion=false;store.preferences.edit().putBoolean("lock_layout",false).commit();store.page=0;invoke("applySettings",new Class[]{boolean.class},true);});
            AtomicReference<FolderSorter> sorted=new AtomicReference<>();main(()->{FolderSorter plan=new FolderSorter(new ArrayList<>(((AppCatalog)field("catalog")).entries));sorted.set(plan);check(plan.folders.size()==20,"Auto-sort changed the reference's 20 names");check(plan.folders.stream().mapToInt(f->f.children.size()).sum()==plan.appCount,"Auto-sort lost an app");invoke("showAutoSort");});
            capture("auto-sort-preview");click("Create sorted desktop");
            await(()->desktop.getWidth()>0&&store.pages.get(store.page).size()==20,"Sorted desktop was not displayed");SystemClock.sleep(700);
            main(()->{for(int i=0;i<20;i++){LauncherStore.Item folder=store.pages.get(store.page).get(i);check(folder.label.equals(FolderRules.NAMES[i])&&folder.cellX==FolderRules.X[i]&&folder.cellY==FolderRules.Y[i],"Folder arrangement moved: "+folder.label);}LauncherStore reloaded=new LauncherStore(activity);check(reloaded.pageCount()==oldCount+1&&reloaded.pages.get(reloaded.page).size()==20,"Sorted folders did not survive reload");});capture("sorted-folder-pattern");
            main(()->invoke("showSettings"));SettingsStudio sortedStudio=(SettingsStudio)field("settingsStudio");main(()->sortedStudio.showPage("motion"));assertPreviewMoves(preview(sortedStudio));capture("transition-preview-sorted-folders");main(()->invoke("closePanel"));
            main(()->{FolderSorter.undo(store);check(store.pageCount()==oldCount,"Auto-sort Undo left its empty screen");store.page=oldCount-1;desktop.rebuild();});
            // Stationary hold still opens a menu; moving after the same hold starts a native drag.
            openFiltered("Scene studio");View tile=drawerTile("Scene studio");hold(tile);await(()->find(v->v instanceof TextView&&"Add to this desktop".contentEquals(((TextView)v).getText()))!=null,"Stationary drawer hold did not open its menu");main(()->invoke("closePanel"));
            openFiltered("Scene studio");tile=drawerTile("Scene studio");dragToEdge(tile,false);
            await(()->store.pageCount()==oldCount+1&&store.pages.get(oldCount).stream().anyMatch(i->i.key.equals("builtin:modes")),"Drawer drag did not create a screen and place the shortcut");capture("drawer-drag-new-desktop");
            openFiltered("Scene studio");tile=drawerTile("Scene studio");dragToEdge(tile,true);
            await(()->store.pageCount()==oldCount+1&&!((DrawerDragController)field("drawerDrags")).active(),"Canceled drag left an empty new screen");
            LauncherStore.Item folder=store.folders().get(0);String folderId=folder.id;int children=folder.children.size();
            main(()->invoke("showStart"));click("Folders");View folderTile=drawerTile(folder.label);check(folderTile!=null,"Drawer Folders tab did not expose existing folders");dragToCenter(folderTile);
            await(()->store.pages.get(store.page).stream().anyMatch(i->i.id.equals(folderId)&&i.children.size()==children),"Folder drawer drag lost its identity or contents");
            check(store.pages.stream().flatMap(Collection::stream).filter(i->i.id.equals(folderId)).count()==1,"Folder drag duplicated its identity");
            main(()->invoke("showSettings"));SettingsModel model=(SettingsModel)field("settingsModel");SettingsStudio studio=(SettingsStudio)field("settingsStudio");Field f=SettingsStudio.class.getDeclaredField("preview");f.setAccessible(true);SettingsPreview preview=(SettingsPreview)f.get(studio);
            main(()->studio.showPage("motion"));
            for(int effect=0;effect<LauncherStore.TRANSITIONS.length;effect++){final int value=effect;main(()->{model.set("transition",value);preview.playTransition();});SystemClock.sleep(140);check(store.transition==effect,"Transition choice was not saved");if(effect==0||effect==10||effect==12||effect==14)capture("transition-preview-"+effect);}
            main(()->{store.page=store.appendPage();desktop.rebuild();store.transition=0;preview.page("motion");});assertPreviewMoves(preview);capture("transition-preview-empty-desktop");
            main(()->{store.transition=7;store.reducedMotion=true;preview.playTransition();});Field running=SettingsPreview.class.getDeclaredField("transitionRunning");running.setAccessible(true);check(!(Boolean)running.get(preview),"Reduced motion allowed preview animation");
            main(()->{store.reducedMotion=false;model.set("home_rotation",3);});await(()->activity.getWindow().getDecorView().getWidth()>activity.getWindow().getDecorView().getHeight(),"Landscape setting did not rotate Home");capture("home-rotation-landscape");
            main(()->model.set("home_rotation",2));await(()->activity.getWindow().getDecorView().getHeight()>activity.getWindow().getDecorView().getWidth(),"Portrait setting did not rotate Home");
            recordingRegression();
            new DesktopManagementSmoke(test,activity,output).run();
        }finally{
            main(()->{((DrawerDragController)field("drawerDrags")).cancel();invoke("closePanel");restore(store.preferences,before);store.pages.clear();try{org.json.JSONArray all=new org.json.JSONArray(layout);for(int p=0;p<oldCount;p++){List<LauncherStore.Item> items=new ArrayList<>();org.json.JSONArray array=all.getJSONArray(p);for(int n=0;n<array.length();n++)items.add(LauncherStore.Item.read(array.getJSONObject(n),0));store.pages.add(items);}}catch(org.json.JSONException e){throw new AssertionError(e);}store.page=oldPage;store.transition=oldTransition;store.mode=oldMode;store.reducedMotion=oldReduced;store.save();invoke("applySettings",new Class[]{boolean.class},true);});
        }
    }
    private void recordingRegression()throws Exception{
        main(()->invoke("showStart"));SystemClock.sleep(350);View grid=find(v->v instanceof GridView);View tile=((GridView)grid).getChildAt(0);check(tile instanceof IconTile,"Unfiltered drawer first icon missing");
        String label=tile.getContentDescription().toString();String key=((AppCatalog)field("catalog")).entries.stream().filter(e->e.label.equals(label)).findFirst().get().key;
        int[] p=point(tile),d=point(desktop);long t=SystemClock.uptimeMillis();pointer(t,0,p[0],p[1]);SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+180);pointer(t,2,p[0],p[1]+90);
        await(()->((DrawerDragController)field("drawerDrags")).tracking(),"Downward hold/move in the unfiltered drawer did not start dragging");pointer(t,2,d[0],d[1]);SystemClock.sleep(200);pointer(t,1,d[0],d[1]);
        await(()->store.pages.get(store.page).stream().anyMatch(i->i.key.equals(key)),"Downward drawer drag dismissed without placing its shortcut");capture("drawer-downward-drag");
        main(()->invoke("showStart"));SystemClock.sleep(350);grid=find(v->v instanceof GridView);tile=((GridView)grid).getChildAt(0);p=point(tile);t=SystemClock.uptimeMillis();pointer(t,0,p[0],p[1]);pointer(t,2,p[0],p[1]+60);pointer(t,2,p[0],p[1]+140);pointer(t,1,p[0],p[1]+140);
        check(field("appsAdapter")!=null,"Scrolling from an app icon dismissed the drawer");main(()->{invoke("closePanel");invoke("showSettings");});SettingsStudio studio=(SettingsStudio)field("settingsStudio");SettingsModel model=(SettingsModel)field("settingsModel");int old=model.value("icon_size");
        main(()->{studio.showPage("nota");ask(studio,"change folder shape");check(studio.page().equals("choice:folder_shape")&&model.value("icon_size")==old,"Folder shape command guessed an icon-size change");model.set("folder_shape",2);});capture("folder-shape-choice");
        main(()->{studio.showPage("nota");model.set("icon_size",80);ask(studio,"change icon size smaller");check(model.value("icon_size")==70,"Recorded smaller command failed");ask(studio,"change icon size large");check(model.value("icon_size")==80,"Recorded large command failed");});
        int count=store.pageCount();main(()->ask(studio,"remove desktop"));check(store.pageCount()==count,"Nota removed a populated desktop");main(()->ask(studio,"add desktop"));check(store.pageCount()==count+1&&store.pages.get(store.page).isEmpty(),"Nota did not add an empty desktop");
        main(()->ask(studio,"remove desktop"));check(store.pageCount()==count,"Nota did not remove the empty desktop");main(()->ask(studio,"add desktop"));
        SettingsPreview preview=preview(studio);await(()->preview.getWidth()>0&&preview.getHeight()>0,"Empty-screen Nota preview not measured");
        main(()->{model.set("icon_size",70);android.graphics.Bitmap small=android.graphics.Bitmap.createBitmap(preview.getWidth(),preview.getHeight(),android.graphics.Bitmap.Config.ARGB_8888),large=android.graphics.Bitmap.createBitmap(preview.getWidth(),preview.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);try{preview.draw(new android.graphics.Canvas(small));model.set("icon_size",130);preview.refresh();preview.draw(new android.graphics.Canvas(large));check(!small.sameAs(large),"Changing icon size on an empty screen left the settings preview empty");}finally{small.recycle();large.recycle();}});capture("nota-empty-screen-preview");
        main(()->{ask(studio,"change transition effect");check(studio.page().equals("choice:transition"),"Nota did not open transition choices");});
        android.content.Context isolated=new android.content.ContextWrapper(activity){@Override public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences("regression071_"+name,mode);}};
        SharedPreferences prefs=isolated.getSharedPreferences("desktop3d",0);prefs.edit().clear().commit();try{LauncherStore s=new LauncherStore(isolated);for(List<LauncherStore.Item> page:s.pages)page.clear();prefs.edit().putString("widget_ids_page_2","347").putBoolean("folder_pattern_page_2",true).commit();check(s.removeEmptyPage(0),"Empty first page could not be removed");check(prefs.getString("widget_ids_page_1","").equals("347")&&prefs.getBoolean("folder_pattern_page_1",false),"Page removal lost the following screen's widget/pattern assignment");check(!s.removeEmptyPage(1),"Widget page was treated as empty");prefs.edit().remove("widget_ids_page_1").commit();check(s.removeEmptyPage(0)&&new LauncherStore(isolated).pageCount()==1&&!s.removeEmptyPage(0),"Page count did not persist at one or allowed removing the last desktop");}finally{prefs.edit().clear().commit();}
    }
    private void ask(SettingsStudio studio,String input){try{Method method=SettingsStudio.class.getDeclaredMethod("ask",String.class);method.setAccessible(true);method.invoke(studio,input);}catch(Exception e){throw new AssertionError(e);}}
    private SettingsPreview preview(SettingsStudio studio){try{Field f=SettingsStudio.class.getDeclaredField("preview");f.setAccessible(true);return (SettingsPreview)f.get(studio);}catch(Exception e){throw new AssertionError(e);}}
    private void assertPreviewMoves(SettingsPreview preview){
        if(!android.animation.ValueAnimator.areAnimatorsEnabled())return;
        await(()->preview.getWidth()>0&&preview.getHeight()>0,"Transition preview was not measured");
        main(()->{try{preview.playTransition();Field field=SettingsPreview.class.getDeclaredField("transitionAnimator");field.setAccessible(true);android.animation.ValueAnimator animator=(android.animation.ValueAnimator)field.get(preview);check(animator!=null,"Preview animation missing");animator.pause();int w=preview.getWidth(),h=preview.getHeight();android.graphics.Bitmap first=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888),second=android.graphics.Bitmap.createBitmap(w,h,android.graphics.Bitmap.Config.ARGB_8888);try{animator.setCurrentFraction(.05f);preview.draw(new android.graphics.Canvas(first));animator.setCurrentFraction(.18f);preview.draw(new android.graphics.Canvas(second));int[] a=new int[w*h],b=new int[w*h];first.getPixels(a,0,w,0,0,w,h);second.getPixels(b,0,w,0,0,w,h);int changed=0;for(int n=0;n<a.length;n++)if(a[n]!=b[n])changed++;check(changed>60,"Transition preview remained visually empty on a sorted or empty desktop");}finally{animator.cancel();first.recycle();second.recycle();}}catch(ReflectiveOperationException error){throw new AssertionError(error);}});
    }
    private void defaultFeed(){SharedPreferences prefs=activity.getSharedPreferences("desktop3d_crystal",0);Map<String,?> before=new HashMap<>(prefs.getAll());try{prefs.edit().clear().commit();check(new CrystalPreferences(activity).feedProvider()==0,"Fresh install does not default to Google");for(int provider:new int[]{0,1,2,3}){prefs.edit().clear().putInt("feed_provider",provider).putBoolean("feed_enabled",false).commit();CrystalPreferences migrated=new CrystalPreferences(activity);check(migrated.feedProvider()==(provider==2?0:provider)&&!migrated.feedEnabled(),"Google migration overwrote explicit feed-off or another provider");}}finally{restore(prefs,before);}}
    private void openFiltered(String name){main(()->{invoke("showStart");((EditText)field("appSearch")).setText(name);});await(()->drawerTile(name)!=null,"Filtered drawer shortcut missing");SystemClock.sleep(350);}
    private View drawerTile(String name){View grid=find(v->v instanceof GridView);return grid==null?null:find(grid,v->v instanceof IconTile&&name.contentEquals(v.getContentDescription()));}
    private void hold(View v){check(v!=null,"Held drawer item missing");int[] p=point(v);long t=SystemClock.uptimeMillis();pointer(t,MotionEvent.ACTION_DOWN,p[0],p[1]);SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+180);pointer(t,MotionEvent.ACTION_UP,p[0],p[1]);}
    private void startDrag(View v){int[] p=point(v);long t=SystemClock.uptimeMillis();dragTime=t;pointer(t,0,p[0],p[1]);SystemClock.sleep(ViewConfiguration.getLongPressTimeout()+180);pointer(t,2,p[0]+30,p[1]+5);await(()->((DrawerDragController)field("drawerDrags")).tracking(),"Drawer native drag did not start after hold/move");}
    private long dragTime;
    private void dragToCenter(View v){int[] d=point(desktop);startDrag(v);pointer(dragTime,2,d[0],d[1]);SystemClock.sleep(250);pointer(dragTime,1,d[0],d[1]);await(()->!((DrawerDragController)field("drawerDrags")).active(),"Folder drag did not finish");}
    private void dragToEdge(View v,boolean cancel){int[] d=point(desktop);View root=(View)field("root");int[] r=new int[2];main(()->root.getLocationOnScreen(r));int count=store.pageCount();startDrag(v);pointer(dragTime,2,r[0]+root.getWidth()-4,d[1]);await(()->store.pageCount()==count+1&&store.page==count,"Edge hold did not create and display the new desktop");if(cancel){main(()->activity.onBackPressed());await(()->!((DrawerDragController)field("drawerDrags")).active(),"Back did not cancel the native drag");releaseCanceledPointer(dragTime,d[0],d[1]);return;}else{pointer(dragTime,2,d[0],d[1]);SystemClock.sleep(250);}pointer(dragTime,1,d[0],d[1]);if(!cancel)await(()->!((DrawerDragController)field("drawerDrags")).active(),"Shortcut drag did not finish");}
    private int[] point(View v){check(v!=null,"Drag view missing");int[] p=new int[2];main(()->v.getLocationOnScreen(p));p[0]+=v.getWidth()/2;p[1]+=Math.min(v.getHeight()/2,Ui.dp(activity,45));return p;}
    // Android has already canceled and removed the drag input channel. A physical
    // lift may be discarded; its injection result does not describe drag success.
    // Creation, active drag, Back cancellation and rollback remain asserted above.
    private void releaseCanceledPointer(long t,float x,float y){MotionEvent e=MotionEvent.obtain(t,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,x,y,0);e.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);test.getUiAutomation().injectInputEvent(e,true);e.recycle();}
    private void pointer(long t,int action,float x,float y){MotionEvent e=MotionEvent.obtain(t,SystemClock.uptimeMillis(),action,x,y,0);e.setSource(android.view.InputDevice.SOURCE_TOUCHSCREEN);check(test.getUiAutomation().injectInputEvent(e,true),"Native drag input rejected");e.recycle();SystemClock.sleep(40);}
    private void click(String text){main(()->{View v=find(w->w instanceof TextView&&text.contentEquals(((TextView)w).getText()));check(v!=null,"Missing "+text);v.performClick();});SystemClock.sleep(250);}
    private View find(java.util.function.Predicate<View> match){return find(activity.getWindow().getDecorView(),match);}private View find(View v,java.util.function.Predicate<View> match){if(v.getVisibility()!=View.VISIBLE)return null;if(match.test(v))return v;if(v instanceof android.view.ViewGroup)for(int i=0;i<((android.view.ViewGroup)v).getChildCount();i++){View child=find(((android.view.ViewGroup)v).getChildAt(i),match);if(child!=null)return child;}return null;}
    private Object field(String name){try{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}catch(Exception e){throw new AssertionError(e);}}
    private Object invoke(String name){return invoke(name,new Class[0]);}private Object invoke(String name,Class[] types,Object... args){try{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}catch(Exception e){throw new AssertionError(e);}}
    private void main(Runnable work){test.runOnMainSync(work);}private void await(BooleanSupplier condition,String message){long end=SystemClock.uptimeMillis()+7000;while(SystemClock.uptimeMillis()<end){AtomicReference<Boolean> ok=new AtomicReference<>();main(()->ok.set(condition.getAsBoolean()));if(ok.get())return;SystemClock.sleep(100);}throw new AssertionError(message);}
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private void capture(String name)throws Exception{SystemClock.sleep(350);android.graphics.Bitmap bitmap=test.getUiAutomation().takeScreenshot();check(bitmap!=null,"Screenshot missing");java.io.File dir=output==null?new java.io.File(activity.getExternalFilesDir(null),"verification"):new java.io.File(output);dir.mkdirs();try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(dir,name+".png"))){bitmap.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}}
    private void restore(SharedPreferences prefs,Map<String,?> values){SharedPreferences.Editor e=prefs.edit().clear();for(Map.Entry<String,?> v:values.entrySet()){Object x=v.getValue();if(x instanceof String)e.putString(v.getKey(),(String)x);else if(x instanceof Integer)e.putInt(v.getKey(),(Integer)x);else if(x instanceof Long)e.putLong(v.getKey(),(Long)x);else if(x instanceof Boolean)e.putBoolean(v.getKey(),(Boolean)x);else if(x instanceof Float)e.putFloat(v.getKey(),(Float)x);}check(e.commit(),"Could not restore test preferences");}
}
